+instruct vcompressBits_masked(vReg dst_src, vReg mask,
+                              vReg tmp1, vReg tmp2, vReg tmp3, vReg tmp4,
+                              vRegMask_V0 v0) %{
+  predicate(Matcher::vector_element_basic_type(n) == T_INT ||
+            Matcher::vector_element_basic_type(n) == T_LONG);
+  match(Set dst_src (CompressBitsV (Binary dst_src mask) v0));
+  effect(TEMP tmp1, TEMP tmp2, TEMP tmp3, TEMP tmp4);
+  format %{ "vcompressBits_masked $dst_src, $dst_src, $mask, $v0\t# KILL $tmp1, $tmp2, $tmp3, $tmp4" %}
+  ins_encode %{
+    BasicType bt = Matcher::vector_element_basic_type(this);
+    __ compress_bits_v(as_VectorRegister($dst_src$$reg),
+                       as_VectorRegister($dst_src$$reg),
+                       as_VectorRegister($mask$$reg),
+                       as_VectorRegister($tmp1$$reg),
+                       as_VectorRegister($tmp2$$reg),
+                       as_VectorRegister($tmp3$$reg),
+                       as_VectorRegister($tmp4$$reg),
+                       bt, Matcher::vector_length(this), Assembler::v0_t);
+  %}
+  ins_pipe(pipe_slow);
+%}
+
